import { createMemo, createSelector, createSignal, For, onCleanup, Show } from "solid-js";
import { render } from "solid-js/web";
import { Combobox } from "@kobalte/core/combobox";

type Source = "incoming" | "outgoing";
type StudyRecord = { id: number; label: string };

const fruits = ["Apricot", "Blueberry", "Cherry"];

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: "row") => void,
) {
  const [incoming, setIncoming] = createSignal(4);
  const [outgoing, setOutgoing] = createSignal(7);
  const [source, setSource] = createSignal<Source>("incoming");
  const [records, setRecords] = createSignal<StudyRecord[]>([
    { id: 1, label: "One" },
    { id: 2, label: "Two" },
    { id: 3, label: "Three" },
    { id: 4, label: "Four" },
  ]);
  const [selected, setSelected] = createSignal<number | null>(null);
  const [isOpen, setOpen] = createSignal(false);
  let disposed = false;

  function Picker() {
    let mounted = true;
    onCleanup(() => { mounted = false; });

    return (
      <Combobox
        options={fruits}
        triggerMode="input"
        onChange={(value) => {
          if (mounted && !disposed && isOpen() && value !== null) onCommit(value);
        }}
        itemComponent={(props) => (
          <Combobox.Item item={props.item}>
            <Combobox.ItemLabel>{props.item.rawValue}</Combobox.ItemLabel>
          </Combobox.Item>
        )}
      >
        <Combobox.Label>Fruit</Combobox.Label>
        <Combobox.Control>
          <Combobox.Input />
          <Combobox.Trigger aria-label="Show fruit options">▾</Combobox.Trigger>
        </Combobox.Control>
        <Combobox.Content>
          <Combobox.Listbox />
        </Combobox.Content>
      </Combobox>
    );
  }

  const unmount = render(() => {
    const badge = createMemo(() => `${source() === "incoming" ? incoming() : outgoing()} crates`);
    const ids = createMemo(() => records().map((record) => record.id));
    const labels = createMemo(() => new Map(records().map((record) => [record.id, record.label])));
    const isSelected = createSelector(selected);

    return (
      <>
        <div>
          <output data-badge="" title={badge()}>{badge()}</output>
          <input data-note="" aria-label="Note" />
        </div>
        <div role="listbox" aria-label="Records">
          <For each={ids()}>
            {(id) => {
              mark("row");
              return (
                <div role="option" data-row={id} aria-selected={isSelected(id) ? "true" : "false"}>
                  <span>{labels().get(id)}</span>
                  <input aria-label={`Edit record ${id}`} />
                </div>
              );
            }}
          </For>
        </div>
        <Show when={isOpen()}><Picker /></Show>
      </>
    );
  }, root);

  function updateRecords(next: StudyRecord[]) {
    const document = root.ownerDocument;
    const active = document.activeElement;
    const editor = active?.tagName === "INPUT" && root.contains(active) && active.closest("[data-row]")
      ? active as HTMLInputElement
      : null;
    const start = editor?.selectionStart;
    const end = editor?.selectionEnd;
    const direction = editor?.selectionDirection;

    setRecords(next);

    if (editor && root.contains(editor)) {
      if (document.activeElement !== editor) editor.focus({ preventScroll: true });
      if (start != null && end != null) editor.setSelectionRange(start, end, direction ?? "none");
    }
  }

  return {
    count(which: Source, value: number) {
      if (which === "incoming") setIncoming(value);
      else setOutgoing(value);
    },
    mode(which: Source) { setSource(which); },
    select(id: number) { setSelected(id); },
    refetch(next: StudyRecord[]) { updateRecords(next.slice()); },
    swap() {
      const next = records().slice();
      if (next.length < 2) return;
      [next[0], next[1]] = [next[1], next[0]];
      updateRecords(next);
    },
    open() { setOpen(true); },
    close() { setOpen(false); },
    dispose() {
      if (disposed) return;
      disposed = true;
      unmount();
    },
  };
}
